// The state database's migrations (packages/core/drizzle, generated by
// drizzle-kit) ship in dist/migrations, where the bundled core looks for
// them next to its own module. `build` runs this after tsdown; only the SQL
// and the journal are needed at run time, not drizzle-kit's snapshots.
//
//   node scripts/copy-migrations.mjs

import { copyFileSync, mkdirSync, readdirSync, rmSync } from 'node:fs';

const from = new URL('../../core/drizzle/', import.meta.url);
const to = new URL('../dist/migrations/', import.meta.url);

rmSync(to, { recursive: true, force: true });
mkdirSync(new URL('meta/', to), { recursive: true });
copyFileSync(
  new URL('meta/_journal.json', from),
  new URL('meta/_journal.json', to),
);
for (const name of readdirSync(from).filter((name) => name.endsWith('.sql')))
  copyFileSync(new URL(name, from), new URL(name, to));
